  function renderMapping(){const d=S.draft;$('#editor').innerHTML=title('Mapping groups',mutatingButton('+ Mapping group','group','','primary'))+`<p class="form-note">Define original NXT groups. Assign each account through its account editor. Optional four-digit GIFI references are metadata; no proprietary mapping catalogue is supplied.</p><div class="card">${table(['Code / group','Kind','GIFI','Accounts',''],d.groups,g=>`<tr><td><div class="mono">${esc(g.code)}</div>${esc(g.name)}</td><td>${esc(pretty(g.kind))}</td><td>${esc(g.gifi_code||'—')}</td><td>${d.accounts.filter(a=>a.group_id===g.id).length}</td><td><div class="row">${mutatingButton('Edit','group',g.id,'sm')}${mutatingButton('Remove','remove-group',g.id,'sm ghost danger')}</div></td></tr>`)}</div><div class="card"><h3>Unassigned accounts</h3>${table(['Code','Account','Action'],d.accounts.filter(a=>!a.group_id),a=>`<tr><td>${esc(a.code)}</td><td>${esc(a.name)}</td><td>${mutatingButton('Assign group','account',a.id,'sm')}</td></tr>`)}</div>`;}
