  function auditMarkup(events){return events.length?`<ol class="audit-list">${events.map(e=>`<li><strong>${esc(pretty(e.action))}</strong><small>${esc(stamp(e.at||e.created_at))}</small><p>${esc(typeof e.detail==='string'?e.detail:'Engagement event recorded')}</p></li>`).join('')}</ol>`:empty('No events recorded','Saved edits, calculations and review decisions appear here.');}
