  function renderImport(){S.preview=null;$('#editor').innerHTML=title('Import a native trial balance')+`<div class="notice"><strong>Preview replaces the account list after commit</strong><p>Use only the native nxt-engagement-tb/v1 format. External Caseware/CaseView/Office databases and proprietary formats are not accepted. Review dependencies and mapping before replacing accounts.</p></div><div class="split"><div class="card">${field('Native JSON file','<input type="file" data-import-file accept=".json,application/json">')}<label class="f" style="margin-top:12px">Or paste native JSON<textarea class="json-editor" data-import-json spellcheck="false" placeholder='{"format":"nxt-engagement-tb/v1","accounts":[]}'></textarea></label>${b('Preview trial balance','preview-import','','primary')}</div><div class="card"><h3>Import preview</h3><div id="import-preview"><p class="form-note">A preview validates the source without changing the engagement. Save other edits before previewing.</p></div></div></div>`;}
