  async function save(){if(!editable())throw Error('Reopen the engagement before editing.');if(!S.dirty)return;const r=await request('/'+enc(S.record.id),{method:'PUT',body:{...S.draft,expected_revision:S.record.revision}});S.record=r;S.draft=clone(r.document);S.dirty=false;S.preview=null;renderWorkspace();toast('Engagement saved');}
