  async function rollforward(){requireSaved();if(S.record.status!=='locked')throw Error('Lock the source engagement before rolling forward.');const d=S.draft,next=value=>{const [y,...rest]=value.split('-');return [Number(y)+1,...rest].join('-');};const r=await dialog('Next-period engagement',`<p class="form-note">Create a separate draft with adjusted balances copied to prior comparatives. Current balances, adjusting entries, paper text and active approvals are cleared. Account/group structure, workpaper types, external URLs (unverified) and planning references remain; only open issues flagged for carryforward are retained.</p><div class="form">${field('Name',input('name',d.name,'text','required maxlength="200"'))}${field('Next period start',input('period_start',next(d.period_start),'date','required'))}${field('Next period end',input('period_end',next(d.period_end),'date','required'))}</div>`,fd=>request('/'+enc(S.record.id)+'/rollforward',{body:{expected_revision:S.record.revision,name:fd.get('name').trim(),period_start:fd.get('period_start'),period_end:fd.get('period_end')}}),'Create next-period draft');if(r){S.section='overview';go('engagement/'+r.id);toast('Next-period draft created');}}
