  async function remove(kind,value){if(!editable())return;const d=S.draft,collections={account:'accounts',group:'groups',paper:'workpapers',adjustment:'adjustments',issue:'issues'},key=collections[kind];if(!key)return;if(kind==='paper'&&list(d.workpapers.find(p=>p.id===value)?.attachment_versions).length)throw Error('This workpaper has immutable file versions and must be retained.');if(kind==='group'&&d.accounts.some(a=>a.group_id===value))throw Error('Unassign the group from its accounts before removing it.');if(kind==='account'&&(d.adjustments.some(a=>a.lines.some(l=>l.account_id===value))||d.workpapers.some(p=>p.account_ids.includes(value))))throw Error('Remove account references from entries and workpapers first.');if(kind==='adjustment'&&d.workpapers.some(p=>p.adjustment_ids.includes(value)))throw Error('Remove workpaper references to this entry first.');if(kind==='paper'&&(d.workpapers.some(p=>p.depends_on.includes(value))||d.issues.some(i=>i.workpaper_id===value)))throw Error('Remove dependent workpaper and issue links first.');if(!await NXT.confirm('Remove from engagement draft?','Remove this item from the current draft? Save to record the change.','Remove'))return;d[key]=d[key].filter(x=>x.id!==value);dirty();renderEditor();}
